  </div>
  <div class="kdn-op-hero">请选择你的猎物</div>
  <div class="kdn-op-cards">
    <div class="kdn-op-card" onclick="jumpGreeting(1)"><div class="c-num">雪乃 · 4 岁</div><div class="c-desc">春苗幼儿园 · 保姆迟到</div></div>
    <div class="kdn-op-card" onclick="jumpGreeting(2)"><div class="c-num">阳乃 · 8 岁</div><div class="c-desc">琴行练琴 · 后门不锁</div></div>
    <div class="kdn-op-card" onclick="jumpGreeting(3)"><div class="c-num">穹 · 7 岁</div><div class="c-desc">小卖部门口 · 只等哥哥</div></div>
    <div class="kdn-op-card" onclick="jumpGreeting(4)"><div class="c-num">真昼 · 6 岁</div><div class="c-desc">独自放学 · 没人来接</div></div>
  </div>
</div>
<script>
(function () {
  var busy = false;
  // Tavern Helper 在 iframe 内注入 getChatMessages/setChatMessage 全局函数。
  // swipes 是字符串数组（元素为开场白原文），setChatMessage 收到字符串会按
  // {message} 处理并配合 swipe_id 完成切换，不触碰 variables/extra——
  // 新 swipe 的楼层变量为空，MVU 检测后按 [initvar] 重新初始化，正合新开局预期。
  window.jumpGreeting = async function (swipeId) {
    if (busy) return;
    busy = true;
    try {
      var messages = await getChatMessages('0', { include_swipe: true });
      var msg = messages && messages[0];
      if (!msg || !msg.swipes || !msg.swipes[swipeId]) {
        alert('开场白 ' + swipeId + ' 不存在，请确认卡片已导入完整开场白。');
        return;
      }
      if (typeof setChatMessage === 'function') {
        await setChatMessage(msg.swipes[swipeId], 0, {
          swipe_id: swipeId,
          refresh: 'display_and_render_current',
        });
      } else if (typeof setChatMessages === 'function') {
        await setChatMessages([{ message_id: 0, swipe_id: swipeId }], { refresh: 'affected' });
      } else {
        alert('当前环境缺少消息切换能力，请使用聊天窗口自带的开场白切换按钮。');
      }
    } catch (err) {
      alert('切换失败：' + ((err && err.message) || err));
    } finally {
      busy = false;
    }
  };
})();
</script>
</body>
